// One leg from routes.txt: where it goes, how far and how much climb
class RouteLeg
{
    public string From { get; set; }       // where the leg starts
    public string To { get; set; }         // where the leg ends
    public double Distance { get; set; }   // kilometres
    public int Climb { get; set; }         // metres of climb
    public string Picture { get; set; }    // the photo's file name

    // Makes one RouteLeg from a line of routes.txt, split at each |
    public RouteLeg(string[] parts)
    {
        From = parts[0];
        To = parts[1];
        Distance = Convert.ToDouble(parts[2]);
        Climb = Convert.ToInt32(parts[3]);
        Picture = parts[4];
    }

    // Reads every leg in routes.txt into a list
    public static List<RouteLeg> LoadAll()
    {
        List<RouteLeg> legs = new List<RouteLeg>();
        string path = Files.Data("routes.txt");
        if (!File.Exists(path)) return legs;   // no file: an empty list
        StreamReader reader = new StreamReader(path);
        while (!reader.EndOfStream)
        {
            string line = reader.ReadLine();
            string[] parts = line.Split('|');
            if (parts.Length != 5) continue;    // skip a broken line
            legs.Add(new RouteLeg(parts));
        }
        reader.Close();
        return legs;
    }

// ---------- the game-form methods from chapter 9 ----------

// Keeps the result on the map, even if the window is then closed
private void KeepResult()
{
    Expedition.Finish(gameNumber, result);
    finished = true;
    lblScore.Text = "Points: " + result.Score;
}

// Fills in the Round over panel and brings it to the front
private void ShowRoundOver()
{
    lblRoundScore.Text = "You scored " + result.Score
        + " out of 100 points.";
    lblWellList.Text = ListText(result.WentWell,
        "thing that went well", "things that went well");
    lblWrongList.Text = ListText(result.WentWrong,
        "thing that went wrong", "things that went wrong");
    if (result.Score >= 60) Sound.Play("win.wav");
    else Sound.Play("lose.wav");
    pnlRoundOver.Visible = true;
    pnlRoundOver.BringToFront();
}

// Up to 3 lines from a list, then how many more there are
private string ListText(List<string> lines, string one, string many)
{
    if (lines.Count == 0) return "Nothing this time.";
    string text = "";
    for (int i = 0; i < lines.Count && i < 3; i++)
    {
        text = text + "- " + lines[i] + Environment.NewLine;
    }
    int more = lines.Count - 3;
    if (more == 1) text = text + "And 1 more " + one + ".";
    if (more > 1) text = text + "And " + more + " more " + many + ".";
    return text;
}

// Back to the map: closing the window runs FormClosing
private void btnBack_Click(object sender, EventArgs e)
{
    this.Close();
}

// The Round over panel's Back to the map button
private void btnDone_Click(object sender, EventArgs e)
{
    this.Close();
}

// Runs as the window closes, by Back, by Done or by the X
private void frmRouteTimer_FormClosing(object sender,
    FormClosingEventArgs e)
{
    if (finished) return;    // a finished round closes at once
    DialogResult answer = MessageBox.Show("Leave Route Timer? It will "
        + "score nothing, but you can come back and climb it again.",
        "Summit Ready", MessageBoxButtons.YesNo);
    if (answer == DialogResult.No) e.Cancel = true;   // stay
}

// Shows the speaker picture that matches the sound being on or off
private void ShowSpeaker()
{
    string icon = "icon-speaker-on-64.png";
    if (Sound.Muted) icon = "icon-speaker-muted-64.png";
    picSound.Image = Files.Picture("Icons", icon);
}

// The speaker picture turns the sound off, or back on
private void picSound_Click(object sender, EventArgs e)
{
    Sound.Muted = !Sound.Muted;
    ShowSpeaker();
}

// ---------- Route Timer ----------
private List<RouteLeg> legs;           // every leg in routes.txt
private int[] order;                   // the legs, mixed up
private int number = 0;                // this leg, 0 to 4
private int total = 0;                 // points from every leg
private List<string> wellLines = new List<string>();
private List<string> wrongLines = new List<string>();

// Puts the next leg on the screen and resets the slider
private void ShowLeg()
{
    RouteLeg leg = legs[order[number]];
    picLeg.Image = Files.Picture("Summits", leg.Picture);
    lblLeg.Text = "Leg " + (number + 1) + " of 5: " + leg.From
        + " to " + leg.To;
    lblFacts.Text = "Distance: " + leg.Distance + " km. Climb: "
        + leg.Climb + " m.";
    trkTime.Value = 0;

    trkTime.Enabled = true;
    lblGuess.Text = "Your guess: " + TimeInWords(0);
    lblWorked.Text = "";
    lblVerdict.Text = "";
    pnlBar.Visible = false;
    btnLock.Visible = true;
    btnNext.Visible = false;
}

// The slider moved: snap it to 5 minutes and show the guess
private void trkTime_Scroll(object sender, EventArgs e)
{
    trkTime.Value = (trkTime.Value + 2) / 5 * 5;
    lblGuess.Text = "Your guess: " + TimeInWords(trkTime.Value);
}

// Turns minutes into words, like 1 hour 55 minutes
private string TimeInWords(int minutes)
{
    int hours = minutes / 60;
    int left = minutes % 60;
    string h = hours + " hours";
    if (hours == 1) h = "1 hour";
    string m = left + " minutes";
    if (left == 1) m = "1 minute";
    if (hours == 0) return m;
    if (left == 0) return h;
    return h + " " + m;
}

private void frmRouteTimer_Load(object sender, EventArgs e)
{
    // Runs once, right before the window first appears
    ShowSpeaker();
    picGuess.Image = Files.Picture("Avatars",
        Expedition.CurrentPlayer.Avatar);
    picFlag.Image = Files.Picture("Icons",
        "icon-chequered-flag-64.png");
    legs = RouteLeg.LoadAll();
    if (legs.Count < 5)
    {
        lblLeg.Text = "Route Timer needs 5 legs in Data\\routes.txt, "
            + "each with 5 parts.";
        return;
    }
    order = Mix.ShuffledNumbers(legs.Count);
    ShowLeg();
}

// Points for a guess that is diff minutes out
private int LegPoints(int diff)
{
    if (diff <= 10) return 20;
    if (diff <= 20) return 12;
    if (diff <= 30) return 5;
    return 0;
}

// Lock in my time: works out Naismith's time and marks the guess
private void btnLock_Click(object sender, EventArgs e)
{
    RouteLeg leg = legs[order[number]];
    int walk = Convert.ToInt32(Math.Round(leg.Distance * 12));
    int climb = leg.Climb / 10;
    int answer = walk + climb;
    int guess = trkTime.Value;
    int diff = Math.Abs(guess - answer);
    int points = LegPoints(diff);

total = total + points;
trkTime.Enabled = false;
btnLock.Visible = false;
Sound.Play("click.wav");
lblWorked.Text = leg.Distance + " km × 12 = " + walk
    + " minutes. " + leg.Climb + " m ÷ 10 = " + climb
    + " minutes. Total: " + answer + " minutes, which is "
    + TimeInWords(answer) + ".";
ShowVerdict(leg, guess, answer, diff, points);
ShowBar(guess, answer);
lblScore.Text = "Points: " + total;

    if (number == 4)
    {
        btnNext.Text = "See my score";
        RecordResult();
    }
    else
    {
        btnNext.Text = "Next leg";
    }
    btnNext.Visible = true;
    btnNext.Focus();
}

// Says which way the guess missed, how far, and the points
private void ShowVerdict(RouteLeg leg, int guess, int answer,
    int diff, int points)
{
    string side = " too long.";
    if (guess < answer) side = " too short.";
    string say;
    if (diff <= 10) say = "Spot on.";
    else if (diff <= 20) say = "Close.";
    else if (diff <= 30) say = "A bit out.";
    else if (guess < answer)
    {
        say = "Too far out. You would still be walking when you "
            + "planned to be finished.";
    }
    else
    {
        say = "Too far out. You planned far more time than this "
            + "leg needs.";
    }

    string missed = "Your guess was exactly right.";
    if (diff == 1) missed = "Your guess was 1 minute" + side;
    if (diff > 1) missed = "Your guess was " + diff + " minutes" + side;
    lblVerdict.Text = missed + " " + say + " " + points + " points.";
    if (points >= 12)
    {
        lblVerdict.ForeColor = Color.FromArgb(62, 142, 65);
        Sound.Play("correct.wav");
    }
    else
    {
        lblVerdict.ForeColor = Color.FromArgb(178, 58, 46);
        Sound.Play("wrong.wav");
    }
    string name = "Your guess for " + leg.From + " to " + leg.To;
    if (diff <= 10) wellLines.Add(name + " was spot on.");
    else if (diff <= 20) wellLines.Add(name + " was close.");
    else wrongLines.Add(name + " was " + diff + " minutes" + side);
}

// Moves the two markers along the bar: 240 minutes is 600 pixels
private void ShowBar(int guess, int answer)
{
    picGuess.Left = guess * 600 / 240;
    picFlag.Left = answer * 600 / 240;
    lblGuessMark.Left = MarkLeft(picGuess.Left);
    lblFlagMark.Left = MarkLeft(picFlag.Left);
    pnlBar.Visible = true;
}

// Puts a marker's words to its right, or to its left near the end
private int MarkLeft(int iconLeft)
{
    if (iconLeft > 460) return iconLeft - 124;
    return iconLeft + 40;
}

// Next leg, or See my score after leg 5
private void btnNext_Click(object sender, EventArgs e)
{
    if (number == 4)
    {
        ShowRoundOver();
        return;
    }
    number++;
    ShowLeg();
}

// Adds the feedback to the result, then keeps it
private void RecordResult()
{
    result = new GameResult("Route Timer", total);
    result.WentWell.AddRange(wellLines);
    result.WentWrong.AddRange(wrongLines);
    KeepResult();
}
